edit(p, """  it("falls back to issue.updated when the issue is un-assigned", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["assigneeId"]);
  });
});
""", """});

describe("issue.unassigned", () => {
  it("is emitted instead of issue.updated when the assignee is cleared", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");
    const unassigned = capture("issue.unassigned");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(0);
    expect(unassigned).toHaveLength(1);
    expect(unassigned[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.admin,
    });
  });

  it("stays silent when the issue had no assignee", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Nobody's" }),
    );

    const updated = capture("issue.updated");
    const unassigned = capture("issue.unassigned");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(updated).toHaveLength(0);
    expect(unassigned).toHaveLength(0);
  });

  it("is not emitted when reassigning from one person to another", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Hand over",
        assigneeId: tenant.userIds.member,
      }),
    );

    const unassigned = capture("issue.unassigned");
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });

    expect(unassigned).toHaveLength(0);
  });

  it("is emitted once per live issue when the assignee leaves the org", async () => {
    const leaving = await createTenant("events-leaving");

    const first = await issueService.createIssue(
      leaving.actors.member,
      issueInput(leaving.org.id, leaving.project.id, {
        title: "Left behind 1",
        assigneeId: leaving.userIds.member,
      }),
    );
    const second = await issueService.createIssue(
      leaving.actors.member,
      issueInput(leaving.org.id, leaving.project.id, {
        title: "Left behind 2",
        assigneeId: leaving.userIds.member,
      }),
    );
    const archived = await issueService.createIssue(
      leaving.actors.member,
      issueInput(leaving.org.id, leaving.project.id, {
        title: "Already archived",
        assigneeId: leaving.userIds.member,
      }),
    );
    await issueService.archiveIssue(leaving.actors.member, leaving.org.id, archived.id);
    await issueService.createIssue(
      leaving.actors.member,
      issueInput(leaving.org.id, leaving.project.id, {
        title: "Someone else's",
        assigneeId: leaving.userIds.admin,
      }),
    );

    const member = await memberRepo.findMember(leaving.org.id, leaving.userIds.member);
    if (!member) throw new Error("fixture member missing");

    const unassigned = capture("issue.unassigned");
    await memberService.removeMember(leaving.actors.admin, {
      orgId: leaving.org.id,
      memberId: member.id,
    });

    expect(unassigned).toHaveLength(2);
    expect(unassigned.map((payload) => payload.issueId).sort()).toEqual(
      [first.id, second.id].sort(),
    );
    for (const payload of unassigned) {
      expect(payload).toMatchObject({
        orgId: leaving.org.id,
        actorId: leaving.userIds.admin,
        projectId: leaving.project.id,
        previousAssigneeId: leaving.userIds.member,
      });
    }

    expect((await issueRepo.findIssueById(leaving.org.id, first.id))?.assigneeId).toBeNull();
    expect((await issueRepo.findIssueById(leaving.org.id, archived.id))?.assigneeId).toBe(
      leaving.userIds.member,
    );
  });
});
""")

