/**
 * Consumers of `issue.unassigned`: the audit log, the notification fan-out
 * and the outgoing-webhook bridge each react to one un-assignment.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import "@/server/services/notification-service";
import { registerWebhookListeners } from "@/server/services/webhook-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("unassigned");
  detachers.push(registerActivityListeners(), registerWebhookListeners());
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

async function unassignedIssue(title: string, assigneeId: UserId, actor = tenant.actors.admin) {
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title, assigneeId }),
  );
  await issueService.assignIssue(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    assigneeId: null,
  });
  return issue;
}

async function unassignedNotifications(recipientId: UserId) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["issue_unassigned"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("issue.unassigned consumers", () => {
  it("records one issue.unassigned audit row", async () => {
    const issue = await unassignedIssue("Audit me", tenant.userIds.member);

    const rows = (
      await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id)
    ).filter((row) => row.action === "issue.unassigned");

    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      action: "issue.unassigned",
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: tenant.project.id,
      actorId: tenant.userIds.admin,
    });
  });

  it("notifies the previous assignee, but never about their own action", async () => {
    const before = (await unassignedNotifications(tenant.userIds.member)).length;
    await unassignedIssue("Notify me", tenant.userIds.member);
    expect(await unassignedNotifications(tenant.userIds.member)).toHaveLength(before + 1);

    const own = (await unassignedNotifications(tenant.userIds.admin)).length;
    await unassignedIssue("Dropped it myself", tenant.userIds.admin, tenant.actors.admin);
    expect(await unassignedNotifications(tenant.userIds.admin)).toHaveLength(own);
  });

  it("queues one delivery per subscribed, enabled endpoint", async () => {
    const subscribed = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://hooks.test/unassigned",
        eventTypes: ["issue.unassigned"],
      },
      "secret-a",
    );
    await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://hooks.test/created",
        eventTypes: ["issue.created"],
      },
      "secret-b",
    );
    const disabled = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://hooks.test/disabled",
        eventTypes: ["issue.unassigned"],
      },
      "secret-c",
    );
    await webhookRepo.updateEndpoint({
      orgId: tenant.org.id,
      webhookId: disabled.id,
      enabled: false,
    });

    const issue = await unassignedIssue("Hook me", tenant.userIds.member);

    const deliveries = (await webhookRepo.claimPendingDeliveries(100)).filter(
      (row) => row.eventType === "issue.unassigned",
    );

    expect(deliveries).toHaveLength(1);
    expect(deliveries[0]?.endpointId).toBe(subscribed.id);
    expect(JSON.parse(deliveries[0]?.payload ?? "{}")).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.member,
    });
  });
});

